 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cycle = [1,2,3,4,5,6,7,8,9]
    # The first row is a full cyclic sequence (except for possible masking).
    # Later rows in these grids have a base row phase one step after row zero;
    # the diagonal copies the previous value, creating the observed staircase.
    first = grid[0][0]
    start = cycle.index(first)
    out = []
    for r in range(h):
        row = [cycle[(start + c) % 9] for c in range(w)]
        if r > 0 and r < w:
            row[r] = row[r-1]
        out.append(row)
    return out

